window.addEventListener("load",function(){const e=document.querySelector(".carousel__slider"),t=e.offsetWidth;let n,o=0;function i(){!function(n){const o=n*t;e.scrollTo({left:o,behavior:"smooth"})}(o=(o+1)%e.children.length)}n=setInterval(i,3e3)});const items=document.querySelectorAll(".little__carousel__slider__item"),fadeDuration=1e3;let currentIndex=0;function fadeOut(e){e.style.transition=`opacity ${fadeDuration}ms`,e.style.opacity=0,setTimeout(()=>{e.style.display="none",showNext()},fadeDuration)}function showNext(){currentIndex=(currentIndex+1)%items.length;const e=items[currentIndex];e.style.transition="none",e.style.display="flex",setTimeout(()=>{fadeIn(e)},100)}function fadeIn(e){e.style.transition=`opacity ${fadeDuration}ms`,e.style.opacity=1,setTimeout(()=>{fadeOut(e)},3e3)}for(let e=1;e<items.length;e++)items[e].style.display="none";fadeIn(items[currentIndex]);